# Older analog layouts overlaid only 12/3/6/9 as TextViews.
# Remove those duplicates now that the dial contains all numbers 1-12.
for name in [
    "widget_local_clock_analog.xml",
    "widget_world_clock_analog_square.xml",
    "widget_world_clock_analog_wide.xml",
    "widget_world_clock_analog_tall.xml",
]:
    p = LAYOUT / name
    text = p.read_text(encoding="utf-8")
    for n in ("12", "3", "6", "9"):
        text = re.sub(
            r'<TextView\b(?:(?!/>).)*?android:text="' + n + r'"(?:(?!/>).)*?/>',
            "",
            text,
            flags=re.S,
        )
    p.write_text(text, encoding="utf-8")

text = GRADLE.read_text(encoding="utf-8")
text = re.sub(r'versionCode\s*=\s*\d+', 'versionCode = 73', text, count=1)
text = re.sub(r'versionName\s*=\s*"[^"]+"', 'versionName = "1.6.2"', text, count=1)
GRADLE.write_text(text, encoding="utf-8")

print("WakeGuard v1.6.2 readable full-number analog clock applied")
